import React, { useState, useEffect } from "react";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import { makeApiRequest } from "../axiosService/ApiCall";
import { Spinner } from "react-bootstrap";
import axios from "axios";

function Nofitication() {
  const [title, setTitle] = useState("");
  const [message, setMessage] = useState("");
  const [titleError, setTitleError] = useState("");
  const [messageError, setMessageError] = useState("");
  const [loading, setIsLoading] = useState(false);
  const [editNotification, setEditNotification] = useState("");
  const [adminType, setAdminType] = useState("");

  // Edit access subadmin....
  const nofiticationEditRes = async () => {
    try {
      let params = {
        url: "view-edit-GetData",
        method: "GET",
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      };
      const EditNotificationRes = await makeApiRequest(params);
      // console.log("EditNotificationRes", EditNotificationRes);
      if (EditNotificationRes.status) {
        const response = EditNotificationRes.data;
        setEditNotification(response.adminPermissions.notification.Edit);
        setAdminType(response.admin_type);
      } else {
        // toast(EditNotificationRes.message);
        console.log(EditNotificationRes.message);
      }
    } catch (error) {
      console.log("err", error);
      // toast.error(error);
    }
  };
  useEffect(() => {
    nofiticationEditRes();
  }, [editNotification]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (editNotification == 0 && adminType == "SubAdmin") {
      toast.warning(
        "Access Denied: You are not allowed to edit Nofitication details."
      );
    } else if (editNotification == 1 || adminType == "SuperAdmin") {
      setIsLoading(true);
      setTitleError("");
      setMessageError("");

      let isValid = true;

      if (!title.trim()) {
        setTitleError("Title is required");
        isValid = false;
        setIsLoading(false);
      }

      if (!message.trim()) {
        setMessageError("Message is required");
        isValid = false;
        setIsLoading(false);
      }

      if (!isValid) {
        setIsLoading(false);
        return;
      }

      const address = await axios.get("https://api.ipify.org/?format=json");

      const lastloginIpAddress = address.data.ip;

      const payload = {
        subject: title.trim(),
        content: message.trim(),
        ip: lastloginIpAddress
      };
      const params = {
        url: "sendPushNotification",
        method: "POST",
        data: payload,
      };

      try {
        let response = await makeApiRequest(params);
        // console.log("response", response);
        if (response.status) {
          toast.success("Push notification sent!");
          setIsLoading(false);
          setTitle("");
          setMessage("");
        } else {
          toast.error("Failed to send notification.");
          setIsLoading(false);
        }
      } catch (error) {
        console.error(error);
        toast.error("An error occurred.");
        setIsLoading(false);
      }
    }
  };

  return (
    <>
      <ToastContainer />
      <div className="container-fluid">
        <div className="row">
          <div className="col-lg-12">
            <h2> Send Push Notification</h2>
            <div className="row">
              <div className="col-lg-6">
                <div className="setting-tabs mt-4">
                  <form onSubmit={handleSubmit}>
                    <div class="mb-3">
                      <label for="exampleFormControlInput1" class="form-label">
                        Title
                      </label>
                      <input
                        type="text"
                        className="form-control"
                        id="exampleFormControlInput1"
                        value={title}
                        disabled={editNotification == 0 && adminType == "SubAdmin"}
                        onChange={(e) => {
                          if (editNotification == 1 || adminType == "SuperAdmin") {
                            // only allow change if editable
                            setTitle(e.target.value);
                            if (titleError) setTitleError("");
                          }
                        }}
                        placeholder="Enter notification title"
                      />
                      {titleError && (
                        <small className="text-danger">{titleError}</small>
                      )}
                    </div>
                    <div className="mb-3">
                      <label
                        for="exampleFormControlTextarea1"
                        className="form-label"
                      >
                        Message
                      </label>
                      <textarea
                        className="form-control"
                        id="exampleFormControlTextarea1"
                        rows="3"
                        value={message}
                        onChange={(e) => {
                          if (editNotification == 1 || adminType == "SuperAdmin") {


                            setMessage(e.target.value);
                            if (messageError) setMessageError("");
                          }
                        }}
                        placeholder="Enter message"
                      // required
                      />
                      {messageError && (
                        <small className="text-danger">{messageError}</small>
                      )}
                    </div>
                    {loading ? (
                      <div className="text-end mt-4">
                        <button className="custom-nav-button-1 active" disabled>
                          {" "}
                          <Spinner size="sm" animation="border" />
                        </button>
                      </div>
                    ) : (
                      <div className="text-end mt-4">
                        <button className="custom-nav-button-1 active">
                          {" "}
                          Send Push notification
                        </button>
                      </div>
                    )}
                  </form>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

export default Nofitication;
